type PostInput = {
  title?: string
  content?: string
}

type PostRouteContext = {
  params: Promise<{ id: string }>
}

export async function GET(
  _request: Request,
  { params }: PostRouteContext
): Promise<Response> {
  const { id } = await params
  const post = {
    id: Number.parseInt(id, 10),
    title: "'`Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return Response.json(post)
}

export async function PUT(
  request: Request,
  { params }: PostRouteContext
): Promise<Response> {
  const { id } = await params
  const { title, content } = (await request.json()) as PostInput
  const updatedPost = {
    id: Number.parseInt(id, 10),
    title: title || `Post ${id}`,
    content: content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return Response.json(updatedPost)
}

export async function DELETE(
  _request: Request,
  { params }: PostRouteContext
): Promise<Response> {
  const { id } = await params
  return Response.json({ message: `Post ${id} deleted successfully` })
}
